class Solution {
public:
    int dfs(TreeNode* node, int parent, int grandparent) {
        if (!node) return 0;
        int total = (grandparent % 2 == 0) ? node->val : 0;
        total += dfs(node->left, node->val, parent);
        total += dfs(node->right, node->val, parent);
        return total;
    }
    int sumEvenGrandparent(TreeNode* root) {
        return dfs(root, 1, 1);
    }
};

class Solution {
    public int sumEvenGrandparent(TreeNode root) {
        return dfs(root, 1, 1);
    }
    private int dfs(TreeNode node, int parent, int grandparent) {
        if (node == null) return 0;
        int total = (grandparent % 2 == 0) ? node.val : 0;
        total += dfs(node.left, node.val, parent);
        total += dfs(node.right, node.val, parent);
        return total;
    }
}

var sumEvenGrandparent = function(root) {
    const dfs = (node, parent, grandparent) => {
        if (!node) return 0;
        let total = (grandparent % 2 === 0) ? node.val : 0;
        total += dfs(node.left, node.val, parent);
        total += dfs(node.right, node.val, parent);
        return total;
    };
    return dfs(root, 1, 1);
};
